esqlQuery.esql:
TS metrics-supabase.metrics.otel-*
// gotrue_running is a gauge: 1 = the Auth service is alive, 0 = it is not.
// MIN() across series so one unhealthy instance is not masked by a healthy one.
| STATS `Auth Running` = MIN(LAST_OVER_TIME(gotrue_running))
    BY resource.attributes.supabase_project_ref
| WHERE `Auth Running` == 0
